import json, sys, datetime

def trunc(s, n=350):
    s = str(s)
    if len(s) > n:
        return s[:n] + f"...[{len(s)}chars]"
    return s

def summarize_content(content):
    parts = []
    if isinstance(content, str):
        return [f"TEXT: {trunc(content)}"]
    if not isinstance(content, list):
        return [trunc(content)]
    for block in content:
        if not isinstance(block, dict):
            parts.append(trunc(block))
            continue
        bt = block.get('type')
        if bt == 'text':
            parts.append(f"TEXT: {trunc(block.get('text',''))}")
        elif bt == 'thinking':
            th = block.get('thinking','')
            if th:
                parts.append(f"THINKING: {trunc(th, 200)}")
        elif bt == 'tool_use':
            name = block.get('name')
            inp = block.get('input', {})
            parts.append(f"TOOL_USE[{name}]: {trunc(json.dumps(inp), 400)}")
        elif bt == 'tool_result':
            c = block.get('content')
            if isinstance(c, list):
                c = ' '.join(trunc(x.get('text','') if isinstance(x,dict) else x, 200) for x in c)
            parts.append(f"TOOL_RESULT(err={block.get('is_error')}): {trunc(c, 300)}")
        else:
            parts.append(trunc(block, 200))
    return parts

def main(path, outpath):
    prev_ts = None
    with open(outpath, 'w') as out:
        with open(path) as f:
            for i, line in enumerate(f):
                line = line.strip()
                if not line:
                    continue
                try:
                    d = json.loads(line)
                except Exception as e:
                    out.write(f"[PARSE ERROR line {i}: {e}]\n")
                    continue
                t = d.get('type', '?')
                ts = d.get('timestamp')
                gap = ""
                if ts and prev_ts:
                    try:
                        t1 = datetime.datetime.fromisoformat(prev_ts.replace('Z','+00:00'))
                        t2 = datetime.datetime.fromisoformat(ts.replace('Z','+00:00'))
                        delta = (t2-t1).total_seconds()
                        if delta > 5:
                            gap = f"  [+{delta:.1f}s]"
                    except Exception:
                        pass
                if ts:
                    prev_ts = ts
                if t in ('user', 'assistant'):
                    msg = d.get('message', {})
                    role = msg.get('role', t)
                    content = msg.get('content')
                    lines = summarize_content(content)
                    out.write(f"--- [{i}] {ts}{gap} {role} ---\n")
                    for l in lines:
                        out.write(f"  {l}\n")
                elif t == 'attachment':
                    hookname = d.get('attachment', {}).get('hookName', '')
                    content = d.get('attachment', {}).get('content', '')
                    out.write(f"--- [{i}] {ts}{gap} ATTACHMENT[{hookname}] ---\n  {trunc(content, 200)}\n")
                elif t == 'queue-operation':
                    out.write(f"--- [{i}] {ts}{gap} QUEUE-OP[{d.get('operation')}] ---\n  {trunc(d.get('content',''), 300)}\n")
                else:
                    out.write(f"--- [{i}] {ts}{gap} {t} ---\n")

if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])

import json, sys
from datetime import datetime

def parse_ts(s):
    return datetime.strptime(s, "%Y-%m-%dT%H:%M:%S.%fZ")

def brief(x, n=220):
    s = str(x)
    s = s.replace("\n", " \\n ")
    return s[:n]

def main(path):
    prev_ts = None
    with open(path) as f:
        for i, line in enumerate(f):
            line = line.strip()
            if not line:
                continue
            try:
                d = json.loads(line)
            except Exception as e:
                print(f"[{i}] PARSE_ERROR {e}")
                continue
            ts = d.get("timestamp")
            dt = parse_ts(ts) if ts else None
            delta = ""
            if dt and prev_ts:
                secs = (dt - prev_ts).total_seconds()
                if secs > 5:
                    delta = f" (+{secs:.1f}s)"
            if dt:
                prev_ts = dt
            typ = d.get("type")
            m = d.get("message")
            if typ in ("user", "assistant") and m:
                role = m.get("role")
                c = m.get("content")
                if isinstance(c, str):
                    print(f"[{i}] {ts}{delta} {typ}/{role} TEXT: {brief(c)}")
                elif isinstance(c, list):
                    for block in c:
                        bt = block.get("type")
                        if bt == "text":
                            print(f"[{i}] {ts}{delta} {typ}/{role} TEXT: {brief(block.get('text',''))}")
                        elif bt == "thinking":
                            print(f"[{i}] {ts}{delta} {typ}/{role} THINKING: {brief(block.get('thinking',''), 150)}")
                        elif bt == "tool_use":
                            print(f"[{i}] {ts}{delta} {typ}/{role} TOOL_USE {block.get('name')}: {brief(block.get('input'), 250)}")
                        elif bt == "tool_result":
                            cont = block.get("content")
                            err = block.get("is_error")
                            print(f"[{i}] {ts}{delta} {typ}/{role} TOOL_RESULT{' ERROR' if err else ''}: {brief(cont, 250)}")
                        else:
                            print(f"[{i}] {ts}{delta} {typ}/{role} BLOCK {bt}")
                else:
                    print(f"[{i}] {ts}{delta} {typ}/{role} <no content>")
            else:
                # other entry types: attachment, last-prompt, mode, etc
                if typ not in ("attachment",):
                    print(f"[{i}] {ts}{delta} {typ}")

if __name__ == "__main__":
    main(sys.argv[1])

import json, sys, datetime

def trunc(s, n=300):
    if s is None: return ""
    s = str(s)
    return s if len(s) <= n else s[:n] + f"...[{len(s)}chars]"

def parse_ts(ts):
    try:
        return datetime.datetime.fromisoformat(ts.replace("Z","+00:00"))
    except Exception:
        return None

def main(path):
    prev_ts = None
    prev_line = None
    idx = 0
    with open(path) as f:
        for line in f:
            line = line.strip()
