                    delta = f"  <<< +{secs:.0f}s since prev"
            if dt:
                prev_ts = dt

            typ = obj.get("type")
            role = None
            content_summary = ""

            if typ == "attachment":
                a = obj.get("attachment", {})
                atype = a.get("type")
                content_summary = f"ATTACHMENT({atype}) {trunc(a.get('content') or a.get('stdout') or a.get('stderr'),150)}"
            elif typ in ("user","assistant"):
                msg = obj.get("message", {})
                role = msg.get("role", typ)
                content = msg.get("content")
                parts = []
                if isinstance(content, str):
                    parts.append(trunc(content, 400))
                elif isinstance(content, list):
                    for c in content:
                        ctype = c.get("type")
                        if ctype == "text":
                            parts.append(f"TEXT: {trunc(c.get('text'),400)}")
                        elif ctype == "tool_use":
                            inp = c.get("input", {})
                            inp_s = trunc(json.dumps(inp), 250)
                            parts.append(f"TOOL_USE[{c.get('name')}]: {inp_s}")
                        elif ctype == "tool_result":
                            cc = c.get("content")
                            if isinstance(cc, list):
                                cc = " ".join(x.get("text","") for x in cc if isinstance(x,dict))
                            parts.append(f"TOOL_RESULT: {trunc(cc,200)}")
                        else:
                            parts.append(f"{ctype}: {trunc(c,150)}")
                content_summary = " | ".join(parts)
            else:
                content_summary = trunc(obj, 150)

            usage = ""
            if typ == "assistant":
                u = obj.get("message",{}).get("usage",{})
                if u:
                    usage = f" [tok in={u.get('input_tokens')} out={u.get('output_tokens')}]"

            print(f"[{idx}] {ts} {typ}/{role or ''}{usage}{delta}\n    {content_summary}")

if __name__ == "__main__":
    main(sys.argv[1])

