import json, sys, datetime

def parse_ts(ts):
    try:
        return datetime.datetime.fromisoformat(ts.replace("Z","+00:00"))
    except Exception:
        return None

def trunc(s, n=350):
    if s is None: return ""
    s = str(s)
    return s if len(s) <= n else s[:n] + f"...[{len(s)}chars]"

def main(path):
    prev_ts = None
    events = []  # (idx, ts, kind, text)
    idx = 0
    with open(path) as f:
        for line in f:
            line = line.strip()
            if not line: continue
            idx += 1
            try:
                obj = json.loads(line)
            except Exception:
                continue
            ts = obj.get("timestamp")
            dt = parse_ts(ts) if ts else None
            delta = None
            if dt and prev_ts:
                delta = (dt - prev_ts).total_seconds()
            if dt:
                prev_ts = dt

            typ = obj.get("type")
            if typ in ("user","assistant"):
                msg = obj.get("message", {})
                role = msg.get("role", typ)
                content = msg.get("content")
                if isinstance(content, str):
                    if content.strip():
                        events.append((idx, ts, delta, f"REAL_{role.upper()}_TEXT", trunc(content, 600)))
                elif isinstance(content, list):
                    for c in content:
                        ctype = c.get("type")
                        if ctype == "text" and role == "user":
                            # user text content that isn't a tool result -> could be system reminder or actual user text
                            t = c.get("text","")
                            events.append((idx, ts, delta, "USER_TEXT_BLOCK", trunc(t,500)))
                        elif ctype == "text" and role == "assistant":
                            events.append((idx, ts, delta, "ASSISTANT_TEXT", trunc(c.get("text",""), 500)))
                        elif ctype == "tool_use":
                            name = c.get("name")
                            inp = c.get("input", {})
                            if name == "AskUserQuestion":
                                events.append((idx, ts, delta, "ASK_USER_QUESTION", trunc(json.dumps(inp), 500)))
                            elif name == "Bash":
                                events.append((idx, ts, delta, "BASH", trunc(inp.get("command",""), 200)))
                            else:
                                events.append((idx, ts, delta, f"TOOL_USE:{name}", trunc(json.dumps(inp), 150)))
            elif typ == "queue-operation":
                pass

    # print long deltas
    print("=== LONG DELTAS (>30s) ===")
    for idx, ts, delta, kind, text in events:
        if delta and delta > 30:
            print(f"[{idx}] {ts} +{delta:.0f}s  ({kind}) {text[:150]}")

    print("\n=== REAL USER TEXT (isUserMessage, not tool_result) ===")
    for idx, ts, delta, kind, text in events:
        if kind in ("REAL_USER_TEXT","USER_TEXT_BLOCK") and not text.startswith("Base directory") and "hookSpecificOutput" not in text:
            print(f"[{idx}] {ts} {kind}: {text}")

    print("\n=== ASK_USER_QUESTION ===")
    for idx, ts, delta, kind, text in events:
        if kind == "ASK_USER_QUESTION":
            print(f"[{idx}] {ts}: {text}")

    print(f"\n=== total events: {len(events)}, first ts: {events[0][1] if events else None}, last ts: {events[-1][1] if events else None} ===")

if __name__ == "__main__":
    main(sys.argv[1])

