import json, sys
from datetime import datetime

def parse_ts(s):
    return datetime.strptime(s, "%Y-%m-%dT%H:%M:%S.%fZ")

def brief(x, n=220):
    s = str(x)
    s = s.replace("\n", " \\n ")
    return s[:n]

def main(path):
    prev_ts = None
    with open(path) as f:
        for i, line in enumerate(f):
            line = line.strip()
            if not line:
                continue
            try:
                d = json.loads(line)
            except Exception as e:
                print(f"[{i}] PARSE_ERROR {e}")
                continue
            ts = d.get("timestamp")
            dt = parse_ts(ts) if ts else None
            delta = ""
            if dt and prev_ts:
                secs = (dt - prev_ts).total_seconds()
                if secs > 5:
                    delta = f" (+{secs:.1f}s)"
            if dt:
                prev_ts = dt
            typ = d.get("type")
            m = d.get("message")
            is_err = False
            if typ in ("user", "assistant") and m:
                role = m.get("role")
                c = m.get("content")
                if isinstance(c, str):
                    print(f"[{i}] {ts}{delta} {typ}/{role} TEXT: {brief(c)}")
                elif isinstance(c, list):
                    for block in c:
                        bt = block.get("type")
                        if bt == "text":
                            print(f"[{i}] {ts}{delta} {typ}/{role} TEXT: {brief(block.get('text',''))}")
                        elif bt == "thinking":
                            print(f"[{i}] {ts}{delta} {typ}/{role} THINKING: {brief(block.get('thinking',''), 150)}")
                        elif bt == "tool_use":
                            print(f"[{i}] {ts}{delta} {typ}/{role} TOOL_USE {block.get('name')}: {brief(block.get('input'), 250)}")
                        elif bt == "tool_result":
                            cont = block.get("content")
                            err = block.get("is_error")
                            print(f"[{i}] {ts}{delta} {typ}/{role} TOOL_RESULT{' ERROR' if err else ''}: {brief(cont, 250)}")
                        else:
                            print(f"[{i}] {ts}{delta} {typ}/{role} BLOCK {bt}")
                else:
                    print(f"[{i}] {ts}{delta} {typ}/{role} <no content>")
            else:
                if typ not in ("attachment",):
                    print(f"[{i}] {ts}{delta} {typ}")
                else:
                    a = d.get("attachment", {})
                    at = a.get("type")
                    if at not in ("skill_listing", "total_tokens_reminder", "task_reminder"):
                        print(f"[{i}] {ts}{delta} attachment/{at}: {brief(a.get('content'), 200)}")

if __name__ == "__main__":
    main(sys.argv[1])

